from openpyxl import load_workbook
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
print('Data rows 1-20 values A-L to identify header row:')
for r in range(1,21):
    vals=[ws.cell(r,c).value for c in range(1,13)]
    if any(v is not None for v in vals):
        print(f'Data row {r}:', vals)
print('\nAll non-empty cells in Data rows 1-20:')
for r in range(1,21):
    entries=[]
    for c in range(1,13):
        v=ws.cell(r,c).value
        if v is not None:
            entries.append(f'{ws.cell(r,c).coordinate}={v!r}')
    if entries:
        print('Row', r, entries)
